import React, { useState } from 'react';
import { Upload, Loader2, Check } from 'lucide-react';
import { base44 } from '@/api/base44Client';

const ALLOWED_EXTS = ['.pdf', '.jpg', '.jpeg', '.png'];
const ALLOWED_MIMES = ['application/pdf', 'image/jpeg', 'image/png'];
const MAX_SIZE = 10 * 1024 * 1024; // 10 MB

// Uploads a file to PRIVATE storage and returns { file_uri, name } to the parent.
// Never produces a public URL — the file_uri can only be accessed via a signed URL
// generated by an authenticated admin.
export default function FileUpload({ label, value, onChange, accept = '.pdf,.jpg,.jpeg,.png' }) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');

  const handle = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file size
    if (file.size > MAX_SIZE) {
      setErr('File is too large. Maximum size is 10 MB.');
      e.target.value = '';
      return;
    }

    // Validate extension
    const ext = '.' + (file.name.split('.').pop() || '').toLowerCase();
    if (!ALLOWED_EXTS.includes(ext)) {
      setErr('Only PDF, JPG, JPEG, and PNG files are allowed.');
      e.target.value = '';
      return;
    }

    // Validate MIME type
    if (file.type && !ALLOWED_MIMES.includes(file.type)) {
      setErr('Invalid file type. Only PDF, JPG, JPEG, and PNG files are allowed.');
      e.target.value = '';
      return;
    }

    setBusy(true);
    setErr('');
    try {
      const { file_uri } = await base44.integrations.Core.UploadPrivateFile({ file });
      onChange({ file_uri, name: file.name });
    } catch (e) {
      setErr(e.message || 'Upload failed. Please try again.');
    }
    setBusy(false);
  };

  return (
    <div>
      {label && <span className="eyebrow">{label}</span>}
      <div className="mt-3 flex flex-wrap items-center gap-3">
        <label className="inline-flex h-12 cursor-pointer items-center gap-2 border border-input px-4 text-sm transition hover:border-foreground/40">
          {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
          {value ? 'Replace file' : 'Upload file'}
          <input type="file" accept={accept} onChange={handle} className="hidden" />
        </label>
        {value && (
          <span className="inline-flex items-center gap-1 text-sm text-success">
            <Check className="h-4 w-4" /> {value.name || 'Attached'}
          </span>
        )}
      </div>
      {err && <p className="mt-2 text-xs text-destructive">{err}</p>}
      <p className="mt-1 text-xs text-muted-foreground">PDF, JPG, JPEG, or PNG only. Max 10 MB. Files are stored securely.</p>
    </div>
  );
}